SELECT COUNT(*)
FROM promotion_slot_allocation
WHERE auction_window_id = #{auctionWindowId}

SELECT id, auction_window_id, resource_type, slot_index, campaign_id, post_id, bidder_user_id, clearing_price, allocation_start_at, allocation_end_at, created_at FROM promotion_slot_allocation WHERE campaign_id IN
#{campaignId}
ORDER BY allocation_start_at DESC, id DESC

SELECT id, auction_window_id, resource_type, slot_index, campaign_id, post_id, bidder_user_id,
       clearing_price, allocation_start_at, allocation_end_at, created_at
FROM promotion_slot_allocation
WHERE resource_type = #{resourceType}
  AND allocation_start_at <= #{now}
  AND allocation_end_at > #{now}
ORDER BY slot_index ASC
